import React, { useEffect, useState } from 'react';
import ExcursionCard from '../../components/Card/ExcursionCard';
import Filter from '../../components/Filter/Filter';
import { getTours } from '../../services/tourService';
import './CatalogPage.css';

const filtersData = {
  Рейтинг: [5, 4, 3, 2, 1],
  Страна: ['Египет', 'Турция'],        // позже будут из API
  Категория: ['История', 'Культура'],  // позже будут из API
  Туроператор: ['TUI', 'Pegas'],
  Тэги: ['Пешая', 'Автобусная', 'Индивидуальная']
};

const CatalogPage = () => {
  const [filters, setFilters] = useState({});
  const [excursions, setExcursions] = useState([]);
  const [loading, setLoading] = useState(true);

  const [favorites, setFavorites] = useState(new Set());
  const [cart, setCart] = useState(new Set());

  useEffect(() => {
    loadTours();
  }, []);

  const loadTours = async () => {
    try {
      const data = await getTours();
      setExcursions(data);
    } catch (error) {
      console.error('Ошибка загрузки туров', error);
    } finally {
      setLoading(false);
    }
  };

  const toggleFavorite = (tourId) => {
    setFavorites(prev => {
      const updated = new Set(prev);
      updated.has(tourId)
        ? updated.delete(tourId)
        : updated.add(tourId);
      return updated;
    });
  };

  const toggleCart = (tourId) => {
    setCart(prev => {
      const updated = new Set(prev);
      updated.has(tourId)
        ? updated.delete(tourId)
        : updated.add(tourId);
      return updated;
    });
  };

  const filteredExcursions = excursions.filter(tour => {
    
    const r = tour.averageRating ? Math.round(tour.averageRating) : 0;

    if (filters['Рейтинг']?.size && !filters['Рейтинг'].has(r)) {
      return false;
    }


    // Страна
    if (
      filters['Страна']?.size &&
      !filters['Страна'].has(tour.city?.country?.name)
    ) {
      return false;
    }

    // Категория
    if (
      filters['Категория']?.size &&
      !filters['Категория'].has(tour.category?.name)
    ) {
      return false;
    }

    // Туроператор
    if (
      filters['Туроператор']?.size &&
      !filters['Туроператор'].has(tour.tourOperator?.name)
    ) {
      return false;
    }

    return true;
  });

  if (loading) {
    return <div className="catalog-loading">Загрузка...</div>;
  }

  return (
    <div className="catalog-wrapper">
      <div className="layout-catalog">
        <Filter filters={filtersData} onChange={setFilters} />

        <main className="content-catalog">
          <div className="catalog-grid">
            {filteredExcursions.map((excursion) => (
              <ExcursionCard
                key={excursion.id}
                excursion={excursion}
                isFavorite={favorites.has(excursion.id)}
                inCart={cart.has(excursion.id)}
                onToggleFavorite={toggleFavorite}
                onToggleCart={toggleCart}
              />
            ))}
          </div>

          {filteredExcursions.length === 0 && (
            <div className="no-results">
              Ничего не найдено по выбранным фильтрам
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default CatalogPage;
